update t_knowledge_point set title = $kp$CD光盘上数字信息的表示$kp$, content = $kp$光盘（CD）以盘面上的凹坑记录数字信息：凹坑的边缘表示“1”，凹坑内外的平坦部分表示“0”。读取时激光束从CD底面照射，依据反射光的变化识别凹坑与平坦区域。$kp$, section = '' where id = 23470;
update t_knowledge_point set title = $kp$信息技术$kp$, content = $kp$信息技术是用来扩展人的信息器官功能、协助人们进行信息处理的一类技术。信息技术引发了第三次工业革命。$kp$, section = '' where id = 23474;
update t_knowledge_point set title = $kp$信息技术发展中的代表性成果$kp$, content = $kp$1938年：彩色电视；1940年代：计算机网络；1960年代：互联网；1990年代：移动电话。$kp$, section = '' where id = 23500;
update t_knowledge_point set title = $kp$四种基本信息技术$kp$, content = $kp$感测（获取）与识别技术——扩展感觉器官功能，提高人们的感知范围、感知精度和灵敏度。
通信技术——扩展神经系统功能，消除人们交流信息的空间和时间障碍。
计算（处理）与存储技术——扩展大脑（思维器官）功能，增强人们的信息加工处理能力。
控制与显示技术——扩展效应器官功能，增强人们的信息控制能力。$kp$, section = '' where id = 23523;
update t_knowledge_point set title = $kp$信息技术的基本特征$kp$, content = $kp$现代信息技术的三大领域是微电子技术、通信技术、数字技术（计算机技术）。当代电子信息技术的基础有两项：微电子与光纤技术、数字技术。现代信息技术的主要特征：以数字技术为基础，以计算机及其软件为核心，采用电子技术（包括激光技术）进行信息的收集、传递、加工、存储、显示与控制。$kp$, section = '' where id = 23595;
update t_knowledge_point set title = $kp$与信息器官功能对应的基本信息技术$kp$, content = $kp$感知与识别技术——扩展感觉器官功能，提高人们的感知范围、感知精度和灵敏度。
通信技术与存储技术——扩展神经网络功能，消除人们交流信息的空间和时间障碍。
计算处理技术——扩展思维器官功能，增强人们的信息加工处理能力。
控制与显示技术——扩展效应器官功能，增强人们的信息控制能力。$kp$, section = '' where id = 23696;
update t_knowledge_point set title = $kp$现代信息技术的领域与特征$kp$, content = $kp$现代信息技术的三大领域是微电子技术、通信技术、数字技术（计算机技术）。当代电子信息技术的基础有两项：微电子与光纤技术、数字技术。现代信息技术的主要特征是以数字技术为基础、以计算机为核心。$kp$, section = '' where id = 23727;
update t_knowledge_point set title = $kp$信息技术与信息化$kp$, content = $kp$信息技术的核心技术包括计算机、软件、集成电路、通信、广播、互联网、自动控制、机器人等。

信息产业（也称“电子信息产业”）是指信息设备生产制造，以及利用这些设备进行信息采集、储存、传递、处理、制作与服务的所有行业与部门的总和，由信息设备制造业、信息服务业、信息内容产业和信息基础设施构成。信息设备制造业生产芯片、计算机、手机、通信设备、数字电视、软件、电子器件等；信息服务业包括通信与广播、电子政务、电子商务、电子金融、网络教育、电子医疗、电子娱乐与游戏等；信息内容产业包括影视制作、动漫与游戏制作、数字文化（音乐、美术、广告等）、电子出版等；信息基础设施包括电信网络、广播电视网络、互联网络等的建设、维护、经营和管理。

在历史长河中，一些科学发现和技术发明曾引发一个国家或民族的跨越式发展和变革，进而导致人类生活方式或国家的根本性变化。蒸汽机的发明引发了第一次工业革命（从英国开始），在很短时间内改变了整个世界的面貌；电动机和发电机的发明引发了第二次工业革命，使电气化与工业化实现有机结合，以美国为代表的工业化国家利用这一结合取得了快速发展，实现了百年的持续发展；信息技术引发了第三次工业革命，20世纪80年代起，美国利用信息技术实现了近30年的持续快速发展，保持了综合实力的领先地位。

产业革命推动社会变革：农业社会由农业革命推动，以土地和农产品种植为基础；工业社会由工业革命推动，以资本与技术、工业化生产为基础；信息社会由信息技术革命推动，以信息资源和信息与知识生产为基础。人类正进入信息社会，表现为信息技术不断创新、信息产业持续发展、信息网络广泛普及。

信息化是由信息技术驱动的经济和社会的变革。信息化的本质是利用信息技术帮助社会个人和群体有效利用知识和新思想，从而建成充分发挥人的潜力、实现其抱负的信息社会。$kp$, section = '' where id = 23801;
update t_knowledge_point set title = $kp$与信息处理相关的行为和活动$kp$, content = $kp$信息收集——感知、测量、识别、获取、输入等；信息加工——分类、计算、分析、综合、转换、检索、管理等；信息存储；信息传递；信息施用——控制、显示等。$kp$, section = '' where id = 23844;
update t_knowledge_point set title = $kp$新一代信息技术$kp$, content = $kp$新一代信息技术分为六个方面：下一代通信网络、物联网、三网融合、新型平板显示、高性能集成电路和以云计算为代表的高端软件。新一代信息技术不只是信息领域一些分支技术（如集成电路、计算机、无线通信等）的纵向升级，更主要的是信息技术整体平台和产业的代际变迁。$kp$, section = '' where id = 23855;
update t_knowledge_point set title = $kp$信息处理的含义$kp$, content = $kp$信息处理指与下列内容相关的行为和活动：信息的收集（如信息的感知、测量、获取、输入等）；信息的传递（如邮寄、出版、电报、电话、广播等）；信息的加工（如分类、计算、分析、转换、检索等）；信息的存储（如书写、摄影、录音、录像等）；信息的施用（如控制、显示、指挥等）。$kp$, section = '' where id = 23863;
update t_knowledge_point set title = $kp$信息的分类$kp$, content = $kp$按产生的先后或加工深度划分：一次信息、二次信息、三次信息。按表现形式划分：文献型、档案型、统计型、动态型、图像型。按来源划分：书本、报刊、电视、人、具体事物。$kp$, section = '' where id = 23878;
update t_knowledge_point set title = $kp$信息化$kp$, content = $kp$信息化是工业社会向信息社会前进的过程，即加快信息高科技发展及其产业化，提高信息技术在经济和社会各领域的推广应用水平并推动经济和社会发展的过程。$kp$, section = '' where id = 23879;
update t_knowledge_point set title = $kp$信息化建设与国家信息基础设施$kp$, content = $kp$1993年，美国政府发表《国家信息基础设施：行动计划》（The National Information Infrastructure: Agenda for Action）。NII由信息资源系统、用户信息设备、本地网络和长途网络组成。NII不等于信息高速公路（Information Superhighways）：信息高速公路只是高水准NII的一个主要组成部分，而NII涉及的是信息活动的全过程与全部环节。$kp$, section = '' where id = 23881;
update t_knowledge_point set title = $kp$信息化与工业化的关系$kp$, content = $kp$信息化与工业化既有本质差别又有一定联系。信息化的内容包括：信息技术、信息基础设施和信息产业本身的快速发展；在经济和社会的各个方面应用信息和信息技术来提高效率和效益，以加速传统工业的发展步伐和提高人们的生活质量。$kp$, section = '' where id = 23889;
update t_knowledge_point set title = $kp$信息技术与人的信息器官$kp$, content = $kp$信息技术是用来扩展人的信息器官功能、协助人们进行信息处理的一类技术。人的信息器官及其功能：感觉器官（眼、耳、鼻、舌、身）——获取信息；神经网络——传递信息；思维器官（大脑）——处理信息并再生信息；效应器官（手脚）——施用信息。$kp$, section = '' where id = 23897;
update t_knowledge_point set title = $kp$基本信息技术的分类$kp$, content = $kp$感知与识别技术——扩展感觉器官功能，提高人们的感知范围、感知精度和灵敏度。
通信技术与存储技术——扩展神经网络功能，消除人们交流信息的空间和时间障碍。
计算处理技术——扩展思维器官功能，增强人们的信息加工处理能力。
控制与显示技术——扩展效应器官功能，增强人们的信息控制能力。$kp$, section = '' where id = 23960;
update t_knowledge_point set title = $kp$汉字编码标准$kp$, content = $kp$GB2312编码是我国1981年颁布的第一个汉字编码国家标准，选出6763个常用汉字和682个非汉字字符，所有字符均采用2字节编码。GB18030包含汉字23940个，与GB2312、GBK保持兼容，同时与UCS接轨，在我国信息处理产品中强制执行；其中ASCII字符采用1字节编码，汉字采用2字节编码，其他字符采用4字节编码。

UCS是国际标准化组织（ISO）制定的将全世界所有文字与符号集中进行统一编码的方案，与之等同的是由微软等公司共同制定的工业标准Unicode。其编码方案有UTF-8和UTF-16等：UTF-8中ASCII字符用1个字节编码，汉字用3个字节编码，其他极少数字符用4个字节编码；UCS-2中ASCII字符和汉字都采用2字节编码，其他不常用字符采用4字节编码。Windows中文版现在使用的UTF-16，也是Java、.NET等软件开发环境默认的编码标准。$kp$, section = '' where id = 24069;
update t_knowledge_point set title = $kp$计算机信息处理的特点$kp$, content = $kp$（1）通用性强、速度高；（2）提供友善的使用方式和多种多样的信息输出形式；（3）具有庞大的信息存储能力和极快的信息存取速度；（4）打破时空限制，实现信息的共享与交流；（5）在辅助开发新的信息处理应用方面能提供有力的支持。$kp$, section = '' where id = 24086;
update t_knowledge_point set title = $kp$计算机的巨大作用$kp$, content = $kp$（1）开拓了人类认识自然、改造自然的新资源；（2）增添了人类发展科学技术的新手段；（3）提供了人类创造文化的新工具；（4）引起了人类工作与生活方式的变化。$kp$, section = '' where id = 24089;
update t_knowledge_point set title = $kp$信息技术的含义与特点$kp$, content = $kp$信息技术是用来扩展人们信息器官功能、帮助人们更有效地进行信息处理的一类技术。现代电子信息技术的主要特征是以数字技术（计算机）为基础，以软件与通信技术为核心，采用电子技术（包括激光技术）进行信息的收集、传递、加工、存储、显示与控制；其两个基础是数字技术和微电子技术，它也是发展信息产业和各项高科技的基础。20世纪80年代，信息技术引发了第三次工业革命。信息技术包括：感测与识别技术——扩展感觉器官功能；通信技术——扩展神经系统功能；计算与存储技术——扩展大脑功能；控制与显示技术——扩展效应器官功能。$kp$, section = '' where id = 25187;
update t_knowledge_point set title = $kp$集成电路的特点与分类$kp$, content = $kp$集成电路是所有电子产品的核心，优点是体积小、重量轻、功耗小、成本低、速度快、可靠性高。现代集成电路使用的半导体材料主要是硅，也可以用砷化镓；制造有400多道工序；工作速度取决于晶体管尺寸，尺寸越小，工作频率越高，速度越快；Moore定律指出单块集成电路的集成度平均每18~24个月翻一番。

按用途分为通用集成电路和专用集成电路（如CPU）；按电路功能分为数字集成电路和模拟集成电路；按晶体管结构与工艺分为双极型电路和金属氧化物半导体（MOS）电路；按集成度（芯片中包含的元器件数目）分为小规模SSI（少于100个）、中规模MSI（100~3000个）、大规模LSI（3000~10万）、超大规模VLSI（10万~几十万）、极大规模ULSI（100万以上），其中超大规模和极大规模统称超大规模（VLSI）。

数字集成电路包括逻辑电路、存储器、微处理器、微控制器、DSP等，模拟集成电路包括信号放大器、功率放大器等；通用集成电路如微处理器和存储器芯片，专用集成电路如ASIC、FPGA。$kp$, section = '' where id = 25189;
update t_knowledge_point set title = $kp$IC卡的分类与特点$kp$, content = $kp$IC卡是集成电路卡或芯片卡的简称。与磁卡相比，它不受磁场影响，能可靠地存储和处理数据。

按集成电路芯片分为：存储卡——容量大约从几KB到几十KB，信息可长期保存，也可通过读卡器更改，可以写入保护和加密，具有一定安全性，如校园卡、公交卡、医保卡、门禁卡；CPU卡——也叫智能卡，卡上集成中央处理器CPU、程序和数据存储器、操作系统，处理能力强，安全性更好，适合信用卡、证件、SIM卡（可保存手机用户的个人识别码、加密密钥和电话簿）。

按使用方式分为：接触式IC卡——表面有一个方形镀金接口，有8个或6个镀金触点，使用时需插入卡机的卡口，存储信息量大、读写操作复杂，但易磨损、怕油污、寿命不长，如手机SIM卡；非接触式IC卡——又叫射频卡、感应卡，卡中无电源，采用电磁感应方式无线传输数据，可读可写，防水、防污、寿命很长，如公交卡、校园卡、第二代身份证。$kp$, section = '' where id = 25190;
update t_knowledge_point set title = $kp$电子标签（RFID）$kp$, content = $kp$电子标签的原理和非接触式IC卡相似，用于检测和跟踪物体。其应用如ETC（车辆不用停车即可缴费）、图书馆找书等；设备可以做成手持式，也可以固定式。$kp$, section = '' where id = 25191;
update t_knowledge_point set title = $kp$信息技术的构成与特征$kp$, content = $kp$信息技术是用来扩展人们信息器官功能、协助人们更有效地进行信息处理的一类技术。现代电子信息技术的主要特征：以数字技术（计算机）为基础，软件与通信技术为核心，采用电子技术（包括激光技术）进行信息的收集、传递、加工、存储、显示与控制；其两个基础是数字技术和微电子技术，它也是发展信息产业和各项高科技的基础。20世纪80年代，信息技术引发了第三次工业革命。信息技术包括：感测与识别技术——扩展感觉器官功能；通信技术——扩展神经系统功能；计算与存储技术——扩展大脑功能；控制与显示技术——扩展效应器官功能。$kp$, section = '' where id = 25281;
update t_knowledge_point set title = $kp$数字技术基础与比特$kp$, content = $kp$数字技术和微电子技术是电子信息技术的重要基础。数字技术只用0和1两个有限状态来表示、处理、存储和传输信息；电子计算机一开始就采用数字技术，通信和信息存储也广泛采用数字技术。

比特是信息的基本单位，数字技术处理的对象是比特（二进制位），比特是数字技术中信息的最小单位。其特点：只有0和1两种状态（取值）；既没有颜色，也没有大小和重量；可以表示数值、文字、符号、图像、声音、命令；CPU内部用高电平表示1、低电平表示0。

比特的存储：计算机和手机的CPU中，比特存储在触发器的双稳态电子线路中，1个触发器存储1个比特，一组触发器可存储多个比特，称为寄存器；电容器也可存储二进制信息，充电表示1、放电表示0。$kp$, section = '' where id = 25282;
update t_knowledge_point set title = $kp$微电子技术$kp$, content = $kp$微电子技术是信息技术领域的关键技术，以集成电路为核心；数字技术与微电子技术是发展信息产业和各项高科技的基础。微电子技术是在电子元器件小型化、微型化的过程中发展起来的，早期的电子技术以真空电子管为基础元件，此后经历了晶体管、中小规模集成电路到大规模、超大规模集成电路的发展。集成电路以半导体单晶片为基片。$kp$, section = '' where id = 25283;
update t_knowledge_point set title = $kp$集成电路的分类与性能$kp$, content = $kp$集成电路是所有电子产品的核心，优点是体积小、重量轻、功耗小、成本低、速度快、可靠性高。现代集成电路使用的半导体材料主要是硅，也可以用砷化镓；制造有400多道工序；工作速度取决于晶体管尺寸，尺寸越小，工作频率越高，速度越快；Moore定律指出单块集成电路的集成度平均每18~24个月翻一番。

按用途分为通用集成电路和专用集成电路，CPU属于通用集成电路；按电路功能分为数字集成电路和模拟集成电路；按晶体管结构与工艺分为双极型电路和金属氧化物半导体（MOS）电路；按集成度分为小规模SSI（少于100个元器件）、中规模MSI（100~3000个）、大规模LSI（3000~10万）、超大规模VLSI（10万~几十万）、极大规模ULSI（100万以上），其中超大规模和极大规模统称超大规模（VLSI）。

数字集成电路包括逻辑电路、存储器、微处理器、微控制器、DSP等，模拟集成电路包括信号放大器、功率放大器等；通用集成电路如微处理器和存储器芯片，专用集成电路如ASIC、FPGA。$kp$, section = '' where id = 25284;
update t_knowledge_point set title = $kp$IC卡与电子标签$kp$, content = $kp$IC卡是集成电路卡或芯片卡的简称，与磁卡相比不受磁场影响，能可靠地存储和处理数据。按集成电路芯片分为存储卡和CPU卡：存储卡容量大约几KB到几十KB，信息可长期保存，也可通过读卡器更改，可以写入保护和加密，如校园卡、公交卡、医保卡、门禁卡；CPU卡也叫智能卡，卡上集成中央处理器CPU、程序和数据存储器、操作系统，处理能力强、安全性更好，适合信用卡、证件、SIM卡。按使用方式分为接触式IC卡和非接触式IC卡：接触式IC卡表面有一个方形镀金接口，有8个或6个镀金触点，使用时需插入卡机的卡口，存储信息量大、读写操作复杂，但易磨损、怕油污、寿命不长，如手机SIM卡；非接触式IC卡又叫射频卡、感应卡，卡中无电池，采用电磁感应方式无线传输数据，可读可写，防水、防污、寿命很长，如公交卡、校园卡、第二代身份证。

电子标签（RFID）的原理和非接触式IC卡相似，用于检测和跟踪物体，如ETC不停车缴费、图书馆找书等，可以做成手持式，也可以固定式。$kp$, section = '' where id = 25285;
update t_knowledge_point set title = $kp$软盘的写保护$kp$, content = $kp$软盘上的写保护滑块用于控制能否向磁盘写入信息：移动滑块露出小窗口即为写保护状态，此时只能读取磁盘上的信息，不能存储信息；滑块盖住窗口时，既能读取磁盘信息，又能将信息存储到磁盘中。$kp$, section = '' where id = 25396;
update t_knowledge_point set title = $kp$一维码与二维码$kp$, content = $kp$一维条形码由一组规则排列的条、空及其对应字符组成，如商品条码“6 71860 01362 4”。

二维条形码的优点是信息容量大、译码可靠性高、纠错能力强、制作成本低、保密与防伪性能好。二维条形码能够在横向和纵向同时表达信息，信息容量大；目前我国广泛使用的是QR码，最多可容纳2710个数字、1850个字母或500多个汉字，也可以表示签字、指纹等信息；其检错和纠错功能较强，能360°全方位识读，可靠性高，还可引入加密技术，具有一定的保密性和防伪性，我国高铁车票的二维条形码就采用了信息加密措施，以防止车票伪造。

二维条形码的识别有两种方法：通过线型扫描器逐层（行）扫描进行解码，或通过照相和图像处理进行解码。堆叠式二维条形码用上述两种方法均可识读，大多数矩阵式二维条形码必须用照相方法识读。由于手机、平板电脑被用作二维条码的扫描器，二维条码的应用已日益普及。

常用的一维码码制包括EAN码、39码、交叉25码、UPC码、128码、93码、ISBN码及Codabar（库德巴码）等。$kp$, section = '' where id = 25613;
update t_knowledge_point set title = $kp$条形码的码制与二维码应用$kp$, content = $kp$常用的一维码码制包括EAN码、39码、交叉25码、UPC码、128码、93码、ISBN码及Codabar（库德巴码）等。39码和128码为国内企业内部自定义码制，可以根据需要确定条码的长度和信息，编码的信息可以是数字，也可以包含字母，主要应用于工业生产线领域、图书管理等；93码是一种类似于39码的条码，密度较高，能够替代39码；25码主要应用于包装、运输以及国际航空系统的机票顺序编号等；Codabar码应用于血库、图书馆、包裹等的跟踪管理；ISBN用于图书管理。

二维条形码常用的码制有Data Matrix、MaxiCode、Aztec、QR Code（日本发明）、Vericode、PDF417、Ultracode、Code 49、Code 16K等，QQ、微信、支付宝等都使用QR Code。二维码分为堆叠式（行排式）和矩阵式：有代表性的行排式二维条码有Code 16K、Code 49、PDF417、MicroPDF417等；有代表性的矩阵式二维条码有Code One、MaxiCode、QR Code、Data Matrix、Han Xin Code、Grid Matrix等。

二维码的功能包括：信息获取（名片、地图、WIFI密码、资料）；网站跳转（跳转到微博、手机网站、网站）；广告推送（扫码直接浏览商家推送的视频、音频广告）；手机电商（扫码直接购物下单）；防伪溯源（扫码查看生产地，后台可获取最终消费地）；优惠促销（下载电子优惠券、抽奖）；会员管理（在手机上获取电子会员信息、VIP服务）；手机支付（通过银行或第三方支付提供的手机端通道完成支付）；账号登录（扫描二维码登录各网站或软件）。$kp$, section = '' where id = 26072;
update t_knowledge_point set title = $kp$信息分类及各类信息的特点$kp$, content = $kp$信息按加工深度划分，可分为一次信息、二次信息、三次信息；按表现形式划分，可分为文献型、档案型、统计型、动态型、图像型；按来源划分，可分为书本、报刊、电视、人、具体事物。

一次信息是指未经加工的原始信息，可以是口头的、图片的、数字的，也可以是表格、清单等。二次信息是指对一次信息进行加工处理后得到的信息，这种信息已经变成规则有序的信息，如文摘、索引、数据卡片等；经过加工后的二次信息易于存储、检索、传递和使用，有较高的使用价值。三次信息是系统地组织、压缩和分析一次信息和二次信息的结果，是通过二次信息所提供的线索，对某一范围的一次信息、二次信息进行分析、综合研究、整理加工生成的信息，是人们深入研究的结晶，综述、专题报告、辞典、年鉴等都属于三次信息。

文献型主要包括各种研究报告、论文、资料以及它们的二次文献等，特点是以文字为主，有明确的专业或学术领域，可以进行编目、分类等排序处理。档案型与文献型有很多相似之处，都以文字为主，不同之处在于档案型信息主要用于反映历史的事实和演变过程，是“事后的”、经过整理和筛选的文献，按时间序列贯穿始终。统计型是数字型信息的集合，是反映大量现象的特征和规律的数字资料，包括以数据为基础的情况分析、趋势分析等内容，其区别于其他类型信息之处在于以数据、图表为主要表现形式。动态型主要是行情、商情、战况等瞬息万变的情况反映，特点是生命周期很短，强调时效性，只有经过加工才能产生有价值的信息；其收集、加工、存储和传递都与其他类型的信息不同，对接收主体的要求很高，需要丰富的知识和分析能力才能利用和判别。图像型以图像为主要表现形式。

来源于书本的信息比较稳定，随时间的变化不大；来源于报纸、杂志、广播、电视和各种报告等的消息具有很强的时效性，超过一定时间其使用价值会大大降低；来源于人与人之间各种交流活动的信息只在很小的范围内流传；来源于具体事物的信息是重要的，同时也最难获得，因为这类信息能增加整个社会的信息量，能给人们带来更多的财富。$kp$, section = '' where id = 26231;
update t_knowledge_point set title = $kp$信息技术的内容与范畴$kp$, content = $kp$信息技术主要研究信息的产生、获取、存储、传输、处理及其应用，也就是扩展人类信息器官功能的技术，其主体技术包括信息获取、传输、处理和存储技术。信息技术的范畴包括传感技术、通信技术、计算机技术和控制技术：传感技术是信息的采集技术，对应于人的感觉器官；通信技术是信息的传递技术，对应于人的神经系统；计算机技术是信息的处理和存储技术，对应于人的思维器官；控制技术是信息的使用技术，对应于人的效应器官。$kp$, section = '' where id = 26233;
update t_knowledge_point set title = $kp$传感器技术$kp$, content = $kp$传感器技术是关于从自然信息源获取信息，并对之进行处理、变换和识别的一门多学科交叉的现代科学与工程技术，涉及传感器和信息处理以及识别的设计、开发、制造、测试、应用及评价等活动。在物联网中，传感技术主要负责接收物品“讲话”的内容；传感器作为信息获取的重要手段，与通信技术和计算机技术共同构成信息技术的三大支柱。

传感器是指能感知预定的被测指标并按照一定规律转换成可用信号的器件和装置，通常由敏感元件、转换元件和转换电路组成。它是一种检测装置，能感受到被测量的信息，并能将检测到的信息按一定规律转换为电信号或其他所需形式的信息输出，以满足信息的传输、处理、存储、显示、记录和控制等要求。

在物联网中，在传感器基础上增加了协同、计算、通信功能，构成具有感知、计算和通信能力的传感器节点。智能化是传感器的重要特点，嵌入式智能技术是实现传感器智能化的重要手段。

传感器按用途可分为力或压力传感器、温度传感器、液位传感器、位移传感器、角度传感器、速度传感器、加速度传感器、烟雾传感器、湿度传感器、流量传感器、转矩传感器等；按工作原理可分为电阻式、电容式、电感式、磁电式、电涡流式、振动式、红外、湿敏、磁敏、气敏、超声波、生物、光电式传感器等。$kp$, section = '' where id = 26367;
update t_knowledge_point set title = $kp$物联网的支撑技术$kp$, content = $kp$支撑技术是指用于物联网数据处理和利用的技术，包括嵌入式计算技术、云计算技术、分布式并行计算、人工智能技术、数据库与数据挖掘技术、多媒体与虚拟现实技术。$kp$, section = '' where id = 26380;
update t_knowledge_point set title = $kp$大数据产生的背景$kp$, content = $kp$信息科技需要解决信息存储、信息传输和信息处理三个核心问题。人类社会在信息科技领域的不断进步，为大数据时代的到来提供了技术支撑。$kp$, section = '' where id = 26520;
update t_knowledge_point set title = $kp$模糊集方法$kp$, content = $kp$模糊集方法即利用模糊集合理论对实际问题进行模糊评判、模糊决策、模糊模式识别和模糊聚类分析。系统的复杂性越高，模糊性越强；模糊集合理论一般用隶属度来刻画模糊事物亦此亦彼的性质。$kp$, section = '' where id = 26556;
update t_knowledge_point set title = $kp$模糊集法$kp$, content = $kp$模糊集法是利用模糊集合理论对问题进行模糊评判、模糊决策、模糊模式识别和模糊聚类分析。模糊集合理论用隶属度来描述模糊事物的属性；系统的复杂性越高，模糊性就越强。$kp$, section = '' where id = 26610;
update t_knowledge_point set title = $kp$信息技术的含义与内容$kp$, content = $kp$信息技术（Information Technology，或Information & Communication Technology，简称IT或ICT）指用来扩展人们信息器官功能、协助人们更有效地进行信息处理的一门技术。其内容包括：扩展感觉器官功能的感测（获取）技术，用于从外部世界获取信息；扩展神经系统功能的通信技术，用于传递信息；扩展大脑功能的计算与存储技术，用于处理信息；扩展效应器官功能的控制与显示技术，用于施用信息。$kp$, section = '' where id = 26914;
update t_knowledge_point set title = $kp$现代信息技术的基础与核心$kp$, content = $kp$信息技术的基本流程：信息获取 → 信息处理 → 信息传输与交换 → 信息存储 → 信息管理 → 信息安全 → 信息的随动执行和应用。

核心技术：集成电路、计算机与软件、通信与广播、互联网、自动控制、机器人。

基础：微（光）电子技术、数字技术、软件技术。$kp$, section = '' where id = 26916;
update t_knowledge_point set title = $kp$传感器的定义$kp$, content = $kp$传感器是一种检测装置，它能感受到被测量的信息，并将其转变成电信号，供计算机进行测量、转换、存储、显示或传输。$kp$, section = '' where id = 27578;
update t_knowledge_point set title = $kp$DVD 光盘与 CD 光盘的差别$kp$, content = $kp$DVD 光盘的道间距比 CD 光盘小，信息凹坑更密集，它使用聚焦更细的红色激光进行信息的读取，盘片的存储容量更大。$kp$, section = '' where id = 27580;
update t_knowledge_point set title = $kp$浏览器插件与 Web 信息检索$kp$, content = $kp$浏览器无法浏览网页中的某些成分时，可以通过安装插件来扩展浏览器的功能。

Web 信息检索包括主题目录和搜索引擎。$kp$, section = '' where id = 27666;
update t_knowledge_point set title = $kp$视频编辑软件$kp$, content = $kp$视频编辑软件：Premiere、Movie Maker。$kp$, section = '' where id = 28370;
update t_knowledge_point set title = $kp$超文本$kp$, content = $kp$采用网状结构组织信息，各信息块按照其内容用指针互相链接起来，使得阅读时可以非常方便地实现快速跳转的一种文本，称为超文本。$kp$, section = '' where id = 29588;
update t_knowledge_point set title = $kp$数据处理（信息处理）$kp$, content = $kp$数据处理（信息处理）是最广泛的应用领域，包括对数据的收集、记载、分类、排序、检索、计算或加工、传输、制表等工作。

例如，在科研、生产和经济活动中，把所获得的大量信息存入计算机，通过加工处理，得到可供某种目的使用的新信息。$kp$, section = '' where id = 29663;
update t_knowledge_point set title = $kp$信息的收集（采集）$kp$, content = $kp$信息的收集（如信息的感知、测量、获取、输入等）。信息的采集是信息处理链中的第一个基本环节，没有好的信息采集技术，信息处理过程就会成为无米之炊。

信息采集过程通常分为 3 个阶段：
1. 信息的识别，以得到正确的信息。
2. 根据不同的目标需求，采用不同的信息采集方法进行信息的采集。
3. 信息的表达，采用文字或符号、数字或编码和声像 3 种信息表达形式对采集到的信息进行表达。$kp$, section = '' where id = 29666;
update t_knowledge_point set title = $kp$信息的收集（采集）$kp$, content = $kp$信息的收集（如信息的感知、测量、获取、输入等）。信息的采集是信息处理链中的第一个基本环节，没有好的信息采集技术，信息处理过程就会成为无米之炊。

信息采集过程通常分为 3 个阶段：
1. 信息的识别，以得到正确的信息。
2. 根据不同的目标需求，采用不同的信息采集方法进行信息的采集。
3. 信息的表达，采用文字或符号、数字或编码和声像 3 种信息表达形式对采集到的信息进行表达。$kp$, section = '' where id = 29670;
update t_knowledge_point set title = $kp$传感器技术$kp$, content = $kp$传感器是指能感知预定的被测指标并按照一定规律转换成可用信号的器件和装置，通常由敏感元件和转换元件组成。

传感器是一种检测装置，能感受到被测量的信息，并能将检测到的信息按一定规律转换为电信号或其他所需形式的信息输出，以满足信息的传输、处理、存储、显示、记录和控制等要求。$kp$, section = '' where id = 29676;
update t_knowledge_point set title = $kp$CD-ROM 光盘$kp$, content = $kp$CD-ROM 光盘上记录的信息是事先制作在光盘上的，用户不能再写入，且记录的信息可以长期保存。$kp$, section = '' where id = 29692;
update t_knowledge_point set title = $kp$信息技术（IT）的含义$kp$, content = $kp$信息技术（IT）指的是用来扩展人们信息器官功能、协助人们更有效地进行信息处理的一门技术（注意：是扩展，不是取代或代替）。

- 雷达、卫星遥感等感测与识别技术扩展了感觉器官。
- 电话、电视、因特网等通信技术扩展了神经系统。
- 计算机、机器人等信息处理与控制技术扩展了大脑的信息加工能力。
- 光、电、磁等信息存储技术扩展了大脑的记忆能力。$kp$, section = '' where id = 29759;
update t_knowledge_point set title = $kp$现代信息技术的三大特征$kp$, content = $kp$1. 技术手段：光和电。
2. 基础：数字技术。
3. 核心：计算机及软件。

核心技术领域是微电子技术、计算机技术、通信技术。

包含的领域：通信、计算机、微电子、自动控制、机器人、遥感遥测等。$kp$, section = '' where id = 29760;
update t_knowledge_point set title = $kp$信息产业$kp$, content = $kp$信息产业是指生产、制造信息设备，以及利用这些设备进行信息的采集、存储、加工、传递、处理、制作和服务的所有行业与部门的总和。$kp$, section = '' where id = 29763;
update t_knowledge_point set title = $kp$信息产业的三大门类$kp$, content = $kp$信息产业主要包括三大门类：
- 信息设备制造业（如制造电子产品）。
- 信息服务业（如通信、广播电视、互联网服务、电子商务等）。
- 信息开发业（如软件产业、电子出版业、游戏与动漫等）。$kp$, section = '' where id = 29764;
update t_knowledge_point set title = $kp$信息产业的特点$kp$, content = $kp$信息产业的特点是：高投入、高风险、增长快、变动大，并具有高度的渗透性、带动性和增值性。$kp$, section = '' where id = 29765;
update t_knowledge_point set title = $kp$微电子技术$kp$, content = $kp$信息技术领域的关键技术是微电子技术，它也是电子信息产业及各项工作高技术的基础，是实现电子电路和电子系统超小型化和微型化的技术。

微电子技术的核心是集成电路技术（IC）。$kp$, section = '' where id = 29766;
update t_knowledge_point set title = $kp$四类基本信息技术$kp$, content = $kp$四类基本信息技术：感测与识别技术、通信与存储技术、计算与处理技术、控制与显示技术。$kp$, section = '' where id = 29798;
update t_knowledge_point set title = $kp$信息技术与人体信息器官的对应关系$kp$, content = $kp$基本的信息技术包括：
- 感觉器官功能——感测（获取）与识别技术。
- 神经网络功能——通信技术。
- 思维器官功能——计算处理技术（加工处理）。
- 效应器官功能——控制与显示技术。$kp$, section = '' where id = 29895;
update t_knowledge_point set title = $kp$现代信息技术的主要特征$kp$, content = $kp$现代信息技术的主要特征是以数字技术为基础，以计算机为核心，采用电子技术（包括激光技术）进行信息的收集、传递、加工、存储、显示与控制（施用）。$kp$, section = '' where id = 29896;
update t_knowledge_point set title = $kp$世界上第一台电子计算机$kp$, content = $kp$世界上第一台计算机占地 200 平方米，重 30 吨，由美国研制，冯·诺依曼提出了“存储程序”原理，它的主要元器件是电子管。计算机最早应用于科学计算，现代计算机应用最广泛的领域是信息处理。$kp$, section = '' where id = 29926;
update t_knowledge_point set title = $kp$信息技术的分类与典型应用$kp$, content = $kp$信息技术是用来扩展人的信息器官功能、协助人们更有效地进行信息处理的一类技术。

基本的信息技术包括：
- 感觉器官功能——感测（获取）与识别技术。
- 神经网络功能——通信技术。
- 思维器官功能——计算处理技术。
- 效应器官功能——控制与显示技术。

典型应用：
- 雷达：以感测与识别为主要目的。
- 电视、广播：以单向、点到多点（面）的信息传递为主要目的。
- 电话：以双向、点到点的信息交互为主要目的。
- 银行：以处理金融信息为目的。

机顶盒的调制与解调：数字机顶盒为单向，互动机顶盒为多向。$kp$, section = '' where id = 29927;
update t_knowledge_point set title = $kp$现代信息技术的领域$kp$, content = $kp$现代信息技术的领域：计算机技术、微电子技术和通信技术。

当代电子信息技术的基础：微电子与光纤技术和数字技术。$kp$, section = '' where id = 29928;
update t_knowledge_point set title = $kp$信息处理与信息技术的含义$kp$, content = $kp$信息处理指的是与信息的收集、传递、加工、存储和施用相关的行为和活动；信息技术则泛指用来扩展人们信息器官功能、协助人们更有效地进行信息处理的一类技术。$kp$, section = '' where id = 29949;
update t_knowledge_point set title = $kp$信息技术的主要内容$kp$, content = $kp$信息技术主要包括信息获取与识别技术、通信与存储技术、计算技术、控制与显示技术等内容。$kp$, section = '' where id = 29950;
update t_knowledge_point set title = $kp$文本处理$kp$, content = $kp$与文本编辑不同，文本处理是对文本中包含的文字信息的音、形、义等进行分析、加工和处理。$kp$, section = '' where id = 29958;
update t_knowledge_point set title = $kp$文本处理与文语转换$kp$, content = $kp$文本处理强调的是使用计算机对文本中所含文字信息的形、音、义等进行分析和处理。文语转换（语音合成）不属于文本处理。$kp$, section = '' where id = 29959;
update t_knowledge_point set title = $kp$信息技术（IT）的特征$kp$, content = $kp$信息技术（IT）的特征是以“数字技术”为基础，以“计算机技术”为核心，采用电子技术和激光技术。$kp$, section = '' where id = 30130;

